export const REALMS=['炼气','筑基','结丹','元婴','化神','炼虚','合体','大乘'];
export const LIFE=[100,200,500,1000,2000,5000,10000,20000];
export const JOBS=['修炼','灵田','坊市','守山'];
export const AREAS=[{name:'落霞山谷',tag:'山野',desc:'溪畔灵草初生，偶有妖狼出没。',level:0,power:28,reward:70,herbs:12},{name:'雾隐古林',tag:'险地',desc:'雾中传来剑鸣，似有前人洞府遗留。',level:1,power:115,reward:240,herbs:32},{name:'沉星秘境',tag:'秘境',desc:'星陨之地封印渐弱，高阶妖兽在此蛰伏。',level:2,power:340,reward:650,herbs:65},{name:'太虚遗墟',tag:'禁地',desc:'空间裂隙深处，飞升者的传承等待来人。',level:4,power:2200,reward:2600,herbs:150}];
export const EVENTS=[{title:'雨夜叩山门',text:'一名负伤散修抱着残破丹经，倒在山门前。他说自己被黑鹫寨追杀，愿以丹经换取庇护。',choices:[{label:'开门救人',hint:'灵石 −50，灵草 +20，族心 +8；外患 +12',money:-50,herbs:20,morale:8,threat:12,result:'丹经中记有养脉之法。山门外，却多了几道窥探的目光。'},{label:'赠药送行',hint:'灵草 −10，声望 +5',herbs:-10,rep:5,result:'散修拱手离去，承诺将来报答这份恩情。'},{label:'闭门避祸',hint:'族心 −4，外患 −4',morale:-4,threat:-4,result:'雨声渐歇。年轻族人对这份谨慎颇有微词。'}]},{title:'灵脉争端',text:'邻近的陆家声称青岚山的一段灵脉归其所有。使者已至议事堂，言辞间多有试探。',choices:[{label:'以礼议和',hint:'灵石 −70，陆家关系 +15，外患 −8',money:-70,relation:15,threat:-8,result:'双方重新划定山界，换来一段安稳岁月。'},{label:'寸土不让',hint:'声望 +12，陆家关系 −18，外患 +12',rep:12,relation:-18,threat:12,result:'族人高声应和。陆家使者拂袖而去。'},{label:'暂让荒坡',hint:'族心 −6，陆家关系 +5',morale:-6,relation:5,result:'一纸旧契划走荒坡，主脉暂时保全。'}]},{title:'少年心事',text:'沈家一名晚辈想离山问道。长辈担心外界凶险，少年却说，困守一山，终究难见大道。',choices:[{label:'资助远游',hint:'灵石 −60，声望 +10，族心 +6',money:-60,rep:10,morale:6,result:'少年记下山门的模样，踏入云雾。族中弟子也燃起求道之心。'},{label:'留山授业',hint:'灵草 −8，全族修为 +12',herbs:-8,xp:12,result:'少年留了下来，将游历之志化为修行之勤。'},{label:'严令禁足',hint:'族心 −8，外患 −5',morale:-8,threat:-5,result:'山门依旧安静，少年眼中的光却暗了一分。'}]},{title:'坊市异宝',text:'云泽坊市流出一枚古旧玉简。摊主不识其物，附近的修士却已悄然围了过来。',choices:[{label:'买下玉简',hint:'灵石 −90，灵草 +25，声望 +8',money:-90,herbs:25,rep:8,result:'玉简标出了隐蔽药圃。你遣族人采回一批灵草。'},{label:'告知摊主',hint:'声望 +8，族心 +3',rep:8,morale:3,result:'摊主感念你的坦诚，沈家的名声在坊市传开。'},{label:'静观其变',hint:'外患 −3',threat:-3,result:'围观者为玉简争执不下，你已悄然离开。'}]},{title:'黑风寨叩关',text:'黑风寨主带着一众凶修堵在山门前，索要青岚山三年供奉。山门外杀气翻涌，退让或应战，皆系一族气运。',choices:[{label:'家主迎敌',hint:'进入战斗；战胜得 160 灵石、18 灵草、声望 +15',battle:{name:'黑风寨主',power:170,reward:160,herbs:18},rep:3,result:'家主执剑而出，黑风寨主狞笑着踏上山阶。'},{label:'开启护山大阵',hint:'灵石 −80，外患 −18；护山大阵等级越高，越易守住',money:-80,threat:-18,result:'阵纹点亮整座青岚山，黑风寨众在山雾中踌躇。'},{label:'交出供奉',hint:'灵石 −140，族心 −10，外患 −6',money:-140,morale:-10,threat:-6,result:'灵石换得一时退兵。族人沉默地望着远去的黑旗。'}]},{title:'云泽拍卖会',text:'云泽坊市十年一度的拍卖会开场。压轴拍品是一枚凝元丹，另有一张残缺秘境图，引得各方修士竞价。',choices:[{label:'竞拍凝元丹',hint:'灵石 −130；全族修为 +18',money:-130,xp:18,result:'凝元丹化开药力，族人修行皆有所得。'},{label:'买下残图',hint:'灵石 −75，灵草 +35，声望 +6',money:-75,herbs:35,rep:6,result:'残图标记的山谷中，果然藏着一片无人采过的药圃。'},{label:'静观强者争夺',hint:'外患 −5，族心 +2',threat:-5,morale:2,result:'你记下各方势力的手段与脸孔，悄然离开拍卖场。'}]}];
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
export function member(id,name,age,talent,realm=0,stage=1){return{id,name,age,talent,realm,stage,xp:0,hp:100,job:'修炼',alive:true,gen:1,trait:['沉稳','果敢','勤勉','机敏'][id%4]};}
export function fresh(){const [a,b,c,d]=uniqueRandomNames(4);return{version:1,year:1,money:360,herbs:65,rep:20,morale:78,threat:18,relation:45,actions:3,debt:0,buildings:{field:1,market:1,hall:1,ward:1},members:[{...member(1,a,38,76,1,1),job:'守山'},{...member(2,b,23,88,0,9),xp:70},{...member(3,c,27,69,0,7),job:'坊市'},{...member(4,d,17,94,0,4),job:'灵田'}],leader:1,nextId:5,event:0,battle:null,end:null,log:[{year:1,type:'story',text:'沈氏四人重归青岚山。断碑犹在，祖训未泯。自今日起，重续一族仙途。'}]};}
export function living(s){return s.members.filter(m=>m.alive);}
export function realmName(m){return REALMS[m.realm]+(m.realm===0?`${m.stage}层`:['初期','中期','后期','圆满'][m.stage-1]);}
export function power(m){return Math.round((22+m.stage*6)*Math.pow(2.8,m.realm)*(m.hp/100)*(.7+m.talent/150));}
export function income(s){return{earn:s.buildings.field*28+s.buildings.market*40+living(s).filter(m=>m.job==='坊市').length*30,upkeep:living(s).length*16+(s.buildings.hall+s.buildings.ward)*6,herbs:s.buildings.field*7+living(s).filter(m=>m.job==='灵田').length*9};}
export function note(s,text,type='normal'){s.log.unshift({year:s.year,text,type});s.log=s.log.slice(0,160);}
function kill(s,m,reason){m.alive=false;m.hp=0;m.died=s.year;note(s,`${m.name}${reason}，享年${m.age}岁。魂归祖祠。`,'death');s.morale=clamp(s.morale-12,0,100);if(m.id===s.leader){const next=living(s).sort((a,b)=>power(b)-power(a))[0];if(next){s.leader=next.id;note(s,`${next.name}接过家主令，承继未竟仙途。`,'story');}}}
function resolveBreakthrough(s,m,major,rng){const chance=major?Math.min(.88,.42+m.talent/250+s.buildings.hall*.015):.95;if(rng()<chance){m.xp=0;if(major&&m.realm===7){s.end=`${m.name}渡过飞升天劫，举霞而去。青岚沈氏传承 ${s.year} 年，终于名列仙门！`;note(s,s.end,'gain');}else{if(major){m.realm++;m.stage=1;}else m.stage++;m.hp=100;s.rep+=major?25:3;note(s,`${m.name}闭关完成，突破至${realmName(m)}${major?'，寿元延至 '+LIFE[m.realm]+' 岁':''}。`,'gain');}}else{m.xp=60;m.hp-=major?45:15;note(s,`${m.name}闭关失败，经脉受损，修为退至六成。`,'death');if(major&&rng()<.1)kill(s,m,'在天劫中陨落');}}
function progressTasks(s,rng){for(const m of living(s)){if(!m.task)continue;m.task.remaining--;if(m.task.remaining>0){note(s,`${m.name}仍在${m.task.type==='heal'?'疗伤':'闭关突破'}，尚余 ${m.task.remaining} 年。`);continue;}const task=m.task;m.task=null;if(task.type==='heal'){m.hp=Math.min(100,m.hp+task.amount);note(s,`${m.name}疗伤期满，气血恢复至 ${m.hp}。`,'gain');}else resolveBreakthrough(s,m,task.major,rng);}}
export function checkEnd(s){if(!living(s).length)s.end='族人尽殁，青岚山再无人守。';else if(s.morale<=0)s.end='族心离散，最后一位族人离开了山门。';else if(s.debt>=3)s.end='连续三年入不敷出，族地被债主收走。';}
const surnames=['沈','顾','林','陆','谢','苏','楚','叶','裴','温','宁','萧'];
const givenNames=['长风','青萝','昭月','知远','怀瑾','听澜','映雪','行舟','望舒','临渊','寻鹤','扶摇','墨白','云舒','若虚','灵均','玉衡','星河','清欢','意迟','逐云','玄霜','照野','望岚'];
export function randomName(rng=Math.random){return surnames[Math.floor(rng()*surnames.length)]+givenNames[Math.floor(rng()*givenNames.length)];}
function uniqueRandomNames(count,rng=Math.random){const result=[],used=new Set();while(result.length<count){const name=randomName(rng);if(!used.has(name)){used.add(name);result.push(name);}}return result;}
function newName(s,rng=Math.random){let name=randomName(rng),tries=0;while(s.members.some(m=>m.name===name)&&tries++<30)name=randomName(rng);return name;}
export function act(s,type,payload={},rng=Math.random){
 if(s.end)throw Error('此世已终，请在存档中开启新一世。');
 if(s.battle&&!['fight','defend','flee'].includes(type))throw Error('请先结束当前战斗。');
 const m=payload.id?living(s).find(x=>x.id===Number(payload.id)):null;
 const use=()=>{if(s.actions<1)throw Error('本年决策已用尽，请推进一年。');s.actions--;};
 if(type==='job'){if(!m||!JOBS.includes(payload.job))throw Error('无效的族人安排。');m.job=payload.job;return;}
 if(type==='rename'){const name=String(payload.name||'').trim();if(!m)throw Error('请选择需要改名的族人。');if(!/^[\u3400-\u9fff]{2,8}$/.test(name))throw Error('名字请使用 2 至 8 个汉字。');if(s.members.some(x=>x.id!==m.id&&x.name===name))throw Error('族谱中已有同名修士。');m.name=name;note(s,`${m.name}改名入谱。`,'story');return;}
 if(type==='event'){if(s.event===null)throw Error('当前没有待处理事件。');const e=EVENTS[s.event],c=e.choices[payload.index];if(!c)throw Error('选择无效。');if(s.money+(c.money||0)<0||s.herbs+(c.herbs||0)<0)throw Error('所需资源不足。');for(const k of ['money','herbs','morale','threat','rep','relation'])s[k]+=c[k]||0;if(c.xp)living(s).forEach(x=>x.xp=Math.min(100,x.xp+c.xp));note(s,`${e.title}：${c.result}`,'story');s.event=null;if(c.battle){const hero=living(s).find(x=>x.id===s.leader);if(hero)s.battle={member:hero.id,area:null,locationName:'青岚山门',enemyName:c.battle.name,enemy:c.battle.power,hp:c.battle.power,max:c.battle.power,reward:c.battle.reward,herbs:c.battle.herbs,turn:1,log:[`${hero.name}在青岚山门迎战${c.battle.name}。`]};}}
 else if(type==='upgrade'){const key=payload.key;if(!Object.hasOwn(s.buildings,key)||s.buildings[key]>=10)throw Error('此产业已达上限。');const cost=s.buildings[key]*100;if(s.money<cost)throw Error(`需要 ${cost} 灵石。`);use();s.money-=cost;s.buildings[key]++;note(s,`${{field:'灵田',market:'坊市',hall:'传功堂',ward:'护山大阵'}[key]}扩建至 ${s.buildings[key]} 级。`,'gain');}
 else if(type==='recruit'){if(s.money<100)throw Error('测灵与安置需要 100 灵石。');if(living(s).length>=16)throw Error('山门最多容纳 16 名修士。');use();s.money-=100;const id=s.nextId++;const n=member(id,newName(s,rng),16,Math.floor(50+rng()*46));n.gen=1+Math.floor((s.year-1)/20);s.members.push(n);note(s,`旁支子弟${n.name}测得灵根，资质 ${n.talent}，入山修行。`,'gain');}
 else if(type==='heal'){if(!m||m.hp>=100)throw Error('该族人无需疗伤。');if(m.task)throw Error('该族人正在进行长期修行。');if(s.herbs<10)throw Error('疗伤需要 10 灵草。');use();s.herbs-=10;m.task={type:'heal',remaining:1,amount:40};note(s,`${m.name}服下疗伤丹，开始为期一年的调息。`);}
 else if(type==='train'){if(!m)throw Error('请选择族人。');if(m.task)throw Error('该族人正在进行长期修行。');if(s.herbs<8)throw Error('需 8 灵草。');if(m.xp>=100)throw Error('修为已满，请尝试突破。');use();s.herbs-=8;m.xp=Math.min(100,m.xp+35);note(s,`${m.name}闭关参悟，修为提升。`,'gain');}
 else if(type==='break'){if(!m||m.xp<100)throw Error('修为达到 100 后方可突破。');if(m.task)throw Error('该族人正在进行长期修行。');if(m.hp<60)throw Error('气血不足 60，请先疗伤。');const major=m.stage===(m.realm===0?13:4),cost=major?80*(m.realm+1):20*(m.realm+1);if(s.money<cost)throw Error(`突破需要 ${cost} 灵石。`);use();s.money-=cost;m.task={type:'break',remaining:major?2:1,major};note(s,`${m.name}进入${major?'两年':'一年'}闭关，突破结果将随岁月揭晓。`);}
 else if(type==='explore'){if(!m||m.hp<40)throw Error('请选择气血不少于 40 的族人。');if(m.task)throw Error('该族人正在进行长期修行。');const a=AREAS[payload.area];if(!a||m.realm<a.level)throw Error('境界不足，尚不能踏入此地。');use();const enemy=Math.round(a.power*(.8+rng()*.4));s.battle={member:m.id,area:payload.area,locationName:a.name,enemyName:'守地妖兽',enemy,hp:enemy,max:enemy,reward:a.reward,herbs:a.herbs,turn:1,log:[`${m.name}踏入${a.name}，遭遇守地妖兽。`]};}
 else if(['fight','defend','flee'].includes(type)){const b=s.battle;if(!b)throw Error('没有正在进行的战斗。');const hero=living(s).find(x=>x.id===b.member);const enemyName=b.enemyName||'强敌';if(type==='flee'&&rng()<.78){note(s,`${hero.name}撤出${b.locationName||'战场'}，保住性命。`);s.battle=null;return;}if(type!=='flee'){const damage=Math.round(power(hero)*(type==='defend'?.34:.65)*(.8+rng()*.4));b.hp=Math.max(0,b.hp-damage);b.log.push(`${type==='defend'?'守势反击':'施展剑诀'}，对${enemyName}造成 ${damage} 点伤害。`);}else b.log.push('撤退受阻！');if(b.hp<=0){const reward=b.reward||0,herbs=b.herbs||0;s.money+=reward;s.herbs+=herbs;hero.xp=Math.min(100,hero.xp+25);s.rep+=8;note(s,`${hero.name}自${b.locationName||'战场'}凯旋，获得 ${reward} 灵石、${herbs} 灵草。`,'gain');s.battle=null;return;}const hit=Math.max(4,Math.round(22*b.enemy/Math.max(20,power(hero))*(type==='defend'?.4:1)*(.8+rng()*.4)));hero.hp=Math.max(0,hero.hp-hit);b.log.push(`${enemyName}反击，${hero.name}气血 −${hit}。`);b.turn++;if(hero.hp<=0){kill(s,hero,`在与${enemyName}的战斗中力竭陨落`);s.battle=null;}}
 else if(type==='year'){if(s.event!==null)throw Error('请先处理本年的家族事件。');s.year++;s.actions=3;const flow=income(s);s.money+=flow.earn-flow.upkeep;s.herbs+=flow.herbs;if(s.money<0){s.money=0;s.debt++;s.morale-=18;note(s,`库藏枯竭，连续亏空 ${s.debt} 年，族心 −18。`,'death');}else{s.debt=0;s.morale+=2;}note(s,`岁末收支：收入 ${flow.earn}，供奉 ${flow.upkeep}，灵草 +${flow.herbs}。`);progressTasks(s,rng);for(const x of living(s)){x.age++;if(x.age>=LIFE[x.realm]){kill(s,x,'寿元耗尽，坐化于洞府');continue;}x.hp=Math.min(100,x.hp+12);const gain=x.job==='修炼'?Math.round(12+x.talent/7+s.buildings.hall*3):7;x.xp=Math.min(100,x.xp+gain);}s.threat+=3;if(s.year%5===0&&living(s).length<16&&living(s).length>=2){const id=s.nextId++;const heir=member(id,newName(s,rng),16,Math.floor(55+rng()*41));heir.gen=2+Math.floor(s.year/20);s.members.push(heir);note(s,`族中晚辈${heir.name}年满十六，测出灵根，列入族谱。`,'story');}if(s.threat>45&&rng()<.4){const guards=living(s).filter(x=>x.job==='守山');const defense=guards.reduce((v,x)=>v+power(x),0)+s.buildings.ward*40;if(defense>s.threat*2){s.rep+=10;note(s,'护山大阵与守山族人击退来犯者，声望 +10。','gain');}else{s.money=Math.max(0,s.money-90);s.morale-=12;const victim=living(s)[Math.floor(rng()*living(s).length)];if(victim){victim.hp-=45;if(victim.hp<=0)kill(s,victim,'守山战败，重伤陨落');}note(s,'外敌破阵，损失最多 90 灵石，族心 −12。','death');}s.threat-=12;}if(living(s).length)s.event=Math.floor(rng()*EVENTS.length);}
 s.morale=clamp(s.morale,0,100);s.threat=clamp(s.threat,0,100);s.relation=clamp(s.relation,0,100);checkEnd(s);
}
